    27|          const crypto = await import('node:crypto');
    28|          const base = (process.env.EXPO_PUBLIC_SUPABASE_URL || '').replace(/\/+$/, '');
    29|          const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || '';
