    32|          const names = ['RENDER_API_KEY','RENDER_SERVICE_ID','IVX_AI_GATEWAY_KEY','AI_GATEWAY_API_KEY'];
    33|          const query = encodeURIComponent(`(${names.join(',')})`);
    34|          const rowsRes = await fetch(`${base}/rest/v1/ivx_owner_variables?select=name,encrypted_value,value_iv,value_tag,value_hash&name=in.${query}`, {
    35|            headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, Accept: 'application/json' }
    36|          });
    37|          if (!rowsRes.ok) throw new Error(`owner variable read HTTP ${rowsRes.status}`);
    38|          const rows = await rowsRes.json();
    39|          const byName = new Map(rows.map(r => [r.name, r]));
    40|          const key = crypto.createHash('sha256').update(encryptionSecret, 'utf8').digest();
    41|          const aad = Buffer.from('ivx_owner_variables:v1', 'utf8');
    42|          function decrypt(name) {
    43|            const row = byName.get(name);
    44|            if (!row) throw new Error(`${name} row missing`);
    45|            const d = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(row.value_iv, 'base64'));
    46|            d.setAAD(aad);
    47|            d.setAuthTag(Buffer.from(row.value_tag, 'base64'));
    48|            const value = Buffer.concat([d.update(Buffer.from(row.encrypted_value, 'base64')), d.final()]).toString('utf8').trim();
    49|            const hash = crypto.createHash('sha256').update(value, 'utf8').digest('hex');
    50|            if (hash !== row.value_hash) throw new Error(`${name} hash verification failed`);
    51|            return value;
    52|          }
    53|          const renderKey = decrypt('RENDER_API_KEY');
    54|          const serviceId = decrypt('RENDER_SERVICE_ID');
    55|          const aiKey = decrypt('IVX_AI_GATEWAY_KEY');
    56|          const aliasKey = byName.has('AI_GATEWAY_API_KEY') ? decrypt('AI_GATEWAY_API_KEY') : aiKey;
    57|          if (aiKey !== aliasKey) throw new Error('AI gateway aliases do not match');
    58|          const headers = { Accept: 'application/json', 'Content-Type': 'application/json', Authorization: `Bearer ${renderKey}` };
    59|          const envUrl = `https://api.render.com/v1/services/${encodeURIComponent(serviceId)}/env-vars`;
    60|          const getRes = await fetch(envUrl, { headers });
