    74|          if (!putRes.ok) throw new Error(`Render env PUT HTTP ${putRes.status}: ${(await putRes.text()).slice(0,160)}`);
    75|          const verifyRes = await fetch(envUrl, { headers });
    76|          if (!verifyRes.ok) throw new Error(`Render env verify GET HTTP ${verifyRes.status}`);
    77|          const verifyRaw = await verifyRes.json();
    78|          const verify = new Map();
    79|          for (const item of verifyRaw) {
    80|            const ev = item.envVar || item;
    81|            if (ev && typeof ev.key === 'string') verify.set(ev.key, typeof ev.value === 'string' ? ev.value : '');
    82|          }
    83|          for (const required of ['IVX_AI_GATEWAY_KEY','AI_GATEWAY_API_KEY','IVX_OWNER_VARIABLES_ENCRYPTION_KEY']) {
    84|            if (!verify.get(required)) throw new Error(`Render post-write validation missing ${required}`);
    85|          }
    86|          console.log(`owner_store_decrypt=PASS rows=${rows.length}`);
    87|          console.log(`render_env_merge=PASS before=${before} after=${verify.size}`);
    88|          console.log('ai_runtime_bindings=PASS');
    89|          const deployRes = await fetch(`https://api.render.com/v1/services/${encodeURIComponent(serviceId)}/deploys`, {
    90|            method: 'POST', headers, body: JSON.stringify({ clearCache: 'do_not_clear' })
    91|          });
    92|          if (!deployRes.ok) throw new Error(`Render deploy trigger HTTP ${deployRes.status}: ${(await deployRes.text()).slice(0,160)}`);
    93|          const deploy = await deployRes.json().catch(() => ({}));
