const crypto = await import('node:crypto');
const base = (process.env.EXPO_PUBLIC_SUPABASE_URL || '').replace(/\/+$/, '');
const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || '';
const encryptionSecrets = [
  process.env.IVX_OWNER_VARIABLES_ENCRYPTION_KEY,
  process.env.APP_SECRET,
  process.env.JWT_SECRET,
].filter(Boolean);
if (!base || !serviceKey || encryptionSecrets.length === 0) throw new Error('required GitHub runtime bindings missing');
const names = ['RENDER_API_KEY','RENDER_SERVICE_ID','IVX_AI_GATEWAY_KEY','AI_GATEWAY_API_KEY'];
const query = encodeURIComponent(`(${names.join(',')})`);
const rowsRes = await fetch(`${base}/rest/v1/ivx_owner_variables?select=name,encrypted_value,value_iv,value_tag,value_hash&name=in.${query}`, {
  headers: { apikey: serviceKey, Authorization: `Bearer ${serviceKey}`, Accept: 'application/json' }
});
if (!rowsRes.ok) throw new Error(`owner variable read HTTP ${rowsRes.status}`);
const rows = await rowsRes.json();
const byName = new Map(rows.map(r => [r.name, r]));
const keyCandidates = [...new Set(encryptionSecrets)].map(secret => crypto.createHash('sha256').update(secret, 'utf8').digest());
const aad = Buffer.from('ivx_owner_variables:v1', 'utf8');
function decrypt(name) {
  const row = byName.get(name);
  if (!row) throw new Error(`${name} row missing`);
  let lastError = null;
  for (const key of keyCandidates) {
    try {
      const d = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(row.value_iv, 'base64'));
      d.setAAD(aad);
      d.setAuthTag(Buffer.from(row.value_tag, 'base64'));
      const value = Buffer.concat([d.update(Buffer.from(row.encrypted_value, 'base64')), d.final()]).toString('utf8').trim();
      const hash = crypto.createHash('sha256').update(value, 'utf8').digest('hex');
      if (hash !== row.value_hash) throw new Error(`${name} hash verification failed`);
      return value;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error(`${name} decryption failed with all key candidates`);
}

